#!/usr/bin/env bash
# Max Player v79 update script
# Run from the repo root: ~/IdeaProjects/maxplayer
set -euo pipefail

if [ ! -f "pubspec.yaml" ]; then
  echo "ERROR: run this from the maxplayer repo root (pubspec.yaml not found here)."
  exit 1
fi

echo "==> Patching lib/utils/ai_subtitles.dart (fix landscape overlap in AI subtitle dialogs)"
python3 - <<'PYEOF'
import sys
p = "lib/utils/ai_subtitles.dart"
s = open(p, encoding="utf-8").read()
count = s.count('''    return AlertDialog(
      backgroundColor: const Color(0xFF1a1a24),
      title: Row(
        children: [
          Icon(Icons.auto_awesome, color: themeState.accent, size: 20),
          const SizedBox(width: 8),
          const Text('AI subtitles', style: TextStyle(color: Colors.white)),
        ],
      ),''')
if count != 2:
    sys.exit(f"[ai_subtitles.dart] expected 2 matches, found {count}, aborting")
s = s.replace(
'''    return AlertDialog(
      backgroundColor: const Color(0xFF1a1a24),
      title: Row(
        children: [
          Icon(Icons.auto_awesome, color: themeState.accent, size: 20),
          const SizedBox(width: 8),
          const Text('AI subtitles', style: TextStyle(color: Colors.white)),
        ],
      ),''',
'''    return AlertDialog(
      // v79: this dialog has real vertical content (2 dropdowns, mode
      // chips, 3 paragraphs of helper text on the options dialog) and had
      // no way to scroll - a short landscape phone screen genuinely
      // couldn't fit it all, so text and the action buttons overlapped.
      // scrollable: true makes AlertDialog wrap content in a scroll view.
      scrollable: true,
      backgroundColor: const Color(0xFF1a1a24),
      title: Row(
        children: [
          Icon(Icons.auto_awesome, color: themeState.accent, size: 20),
          const SizedBox(width: 8),
          const Text('AI subtitles', style: TextStyle(color: Colors.white)),
        ],
      ),''')
open(p, "w", encoding="utf-8").write(s)
print("  OK (patched both AI subtitle dialogs)")
PYEOF

echo "==> Writing android/app/src/main/res/drawable/launch_background.xml (logo, background kept)"
cat > android/app/src/main/res/drawable/launch_background.xml << 'XMLEOF'
<?xml version="1.0" encoding="utf-8"?>
<!-- Modify this file to customize your launch splash screen -->
<layer-list xmlns:android="http://schemas.android.com/apk/res/android">
    <item android:drawable="@android:color/white" />

    <!-- v79: logo shown while the app is cold-starting. Kept its own
         background intact (matches the launcher icon) instead of being
         cut out onto a separate card. -->
    <item android:width="200dp" android:height="200dp" android:gravity="center">
        <bitmap android:gravity="center" android:src="@drawable/splash_logo" />
    </item>
</layer-list>
XMLEOF

