echo "==> Patching lib/widgets/video_ask_sheet.dart (persist AI answers to disk across restarts)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/video_ask_sheet.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[video_ask_sheet.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
"""import 'package:flutter/material.dart';

import '../services/movie_ai.dart';
import '../state/theme_state.dart';
import '../utils/srt.dart';""",
"""import 'dart:async';
import 'dart:convert';

import 'package:flutter/material.dart';

import '../services/movie_ai.dart';
import '../services/native_bridge.dart';
import '../state/theme_state.dart';
import '../utils/srt.dart';""")

apply(
"""  /// v76: in-memory cache of every video's Q&A, so closing this sheet
  /// (a dismissible bottom sheet - Flutter tears its whole State down on
  /// close) doesn't throw away what the AI already generated. Cleared
  /// when the app process dies, same lifetime as the rest of the app's
  /// in-memory state.
  static final Map<String, List<_Msg>> _sessionCache = {};

  @override
  void initState() {
    super.initState();
    _messages = _sessionCache.putIfAbsent(widget.title, () => []);
  }""",
"""  /// v76: in-memory cache of every video's Q&A, so closing this sheet
  /// (a dismissible bottom sheet - Flutter tears its whole State down on
  /// close) doesn't throw away what the AI already generated.
  /// v79: now backed by disk (SharedPreferences via NativeBridge), so it
  /// also survives restarting the app, not just closing this sheet.
  static final Map<String, List<_Msg>> _sessionCache = {};
  static bool _diskLoaded = false;
  static const String _kPrefKey = 'ai.videoAskCache';
  static const int _kMaxVideosCached = 30; // keep the store small on disk

  static Future<void> _loadFromDisk() async {
    if (_diskLoaded) return;
    _diskLoaded = true;
    try {
      final raw = (await NativeBridge.loadSettings())[_kPrefKey];
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      decoded.forEach((title, msgs) {
        _sessionCache[title] = [
          for (final m in (msgs as List))
            _Msg._(
              m['w'] == 'u' ? _Who.user : _Who.ai,
              m['t'] as String,
            ),
        ];
      });
    } catch (_) {
      // Corrupt/old cache - ignore, just start fresh.
    }
  }

  static void _persistToDisk() {
    // Cap how many videos we keep (oldest inserted first, since Dart Map
    // preserves insertion order) so this doesn't grow forever.
    while (_sessionCache.length > _kMaxVideosCached) {
      _sessionCache.remove(_sessionCache.keys.first);
    }
    final encoded = jsonEncode({
      for (final e in _sessionCache.entries)
        e.key: [
          for (final m in e.value) {'w': m.who == _Who.user ? 'u' : 'a', 't': m.text},
        ],
    });
    unawaited(NativeBridge.saveSetting(_kPrefKey, encoded));
  }

  @override
  void initState() {
    super.initState();
    _messages = _sessionCache.putIfAbsent(widget.title, () => []);
    _loadFromDisk().then((_) {
      if (!mounted) return;
      final cached = _sessionCache[widget.title];
      if (cached != null && cached.isNotEmpty && _messages.isEmpty) {
        setState(() {
          _messages
            ..clear()
            ..addAll(cached);
        });
        _scrollToBottom();
      }
    });
  }""")

apply(
"""    if (!mounted || token != _askToken) return;
    setState(() {
      _asking = false;
      _messages.add(_Msg.ai(answer ?? _failedMessage()));
    });
    _scrollToBottom();""",
"""    if (!mounted || token != _askToken) return;
    setState(() {
      _asking = false;
      _messages.add(_Msg.ai(answer ?? _failedMessage()));
    });
    _persistToDisk();
    _scrollToBottom();""")

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/widgets/ask_ai_sheet.dart (persist movie AI answers to disk across restarts)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/ask_ai_sheet.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[ask_ai_sheet.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
"""import 'dart:io';

import 'package:flutter/material.dart';""",
"""import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';""")

apply(
"""  /// v77: in-memory cache of the last question/answer per movie, so
  /// closing this sheet (a dismissible bottom sheet - Flutter tears its
  /// whole State down on close) and reopening it for the same movie
  /// shows what the AI already generated instead of a blank sheet.
  /// Separate from MovieAiClient's 7-day on-disk cache, which only
  /// speeds up re-asking the identical question - this restores what
  /// was actually on screen.
  static final Map<int, ({String question, String answer, String? model})>
      _sessionCache = {};

  @override
  void initState() {
    super.initState();
    _bootCache();
    final cached = _sessionCache[widget.movie.id];
    if (cached != null) {
      _questionCtrl.text = cached.question;
      _answer = cached.answer;
      _answerModel = cached.model;
    }
  }""",
"""  /// v76: in-memory cache of the last question/answer per movie, so
  /// closing this sheet (a dismissible bottom sheet - Flutter tears its
  /// whole State down on close) and reopening it for the same movie
  /// shows what the AI already generated instead of a blank sheet.
  /// Separate from MovieAiClient's 7-day on-disk cache, which only
  /// speeds up re-asking the identical question - this restores what
  /// was actually on screen.
  /// v79: now also backed by disk (SharedPreferences via NativeBridge),
  /// so it survives restarting the app too.
  static final Map<int, ({String question, String answer, String? model})>
      _sessionCache = {};
  static bool _diskLoaded = false;
  static const String _kPrefKey = 'ai.movieAskCache';
  static const int _kMaxMoviesCached = 50;

  static Future<void> _loadCacheFromDisk() async {
    if (_diskLoaded) return;
    _diskLoaded = true;
    try {
      final raw = (await NativeBridge.loadSettings())[_kPrefKey];
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      decoded.forEach((id, v) {
        final m = v as Map<String, dynamic>;
        _sessionCache[int.parse(id)] = (
          question: m['q'] as String,
          answer: m['a'] as String,
          model: m['m'] as String?,
        );
      });
    } catch (_) {
      // Corrupt/old cache - ignore, just start fresh.
    }
  }

  static void _persistCacheToDisk() {
    while (_sessionCache.length > _kMaxMoviesCached) {
      _sessionCache.remove(_sessionCache.keys.first);
    }
    final encoded = jsonEncode({
      for (final e in _sessionCache.entries)
        '${e.key}': {'q': e.value.question, 'a': e.value.answer, 'm': e.value.model},
    });
    unawaited(NativeBridge.saveSetting(_kPrefKey, encoded));
  }

  @override
  void initState() {
    super.initState();
    _bootCache();
    final cached = _sessionCache[widget.movie.id];
    if (cached != null) {
      _questionCtrl.text = cached.question;
      _answer = cached.answer;
      _answerModel = cached.model;
    }
    _loadCacheFromDisk().then((_) {
      if (!mounted || _answer != null) return;
      final diskCached = _sessionCache[widget.movie.id];
      if (diskCached != null) {
        setState(() {
          _questionCtrl.text = diskCached.question;
          _answer = diskCached.answer;
          _answerModel = diskCached.model;
        });
      }
    });
  }""")

apply(
"""        _sessionCache[widget.movie.id] = (
          question: q,
          answer: result.text,
          model: result.model,
        );
      }""",
"""        _sessionCache[widget.movie.id] = (
          question: q,
          answer: result.text,
          model: result.model,
        );
        _persistCacheToDisk();
      }""")

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

